def walltime() -> float:
    return time.perf_counter()


class P1DeadlineReached(RuntimeError):
    """Internal control-flow signal used only to stop P1 at its wall-clock deadline."""


class P1InnerWatchdogNoInterval(RuntimeError):
    """P1 inner watchdog fired before any complete strict RNC lower bound existed."""


def ensure_dir(path: str) -> None:
    os.makedirs(path, exist_ok=True)


def l1_norm(x: np.ndarray) -> float:
    return float(np.sum(np.abs(np.asarray(x, dtype=float))))


def linf_norm(x: np.ndarray) -> float:
    arr = np.asarray(x, dtype=float)
    return float(np.max(np.abs(arr))) if arr.size else 0.0


def format_int_tuple(v: np.ndarray) -> str:
    raw = [int(round(float(x))) for x in np.asarray(v, dtype=float).ravel().tolist()]
    # Convenience display for replicated-Z step-1 variables z=(r1,r2,q1,q2).
    # The actual physical labels are z_phys = r + 15*q.
    if len(raw) == 4 and max(raw[:2] or [0]) <= 14 and min(raw[:2] or [0]) >= 0 and max(raw[2:] or [0]) <= 19 and min(raw[2:] or [0]) >= 0:
        phys = tuple(raw[i] + 15 * raw[i + 2] for i in range(2))
        return f"phys={phys} r={tuple(raw[:2])} q={tuple(raw[2:])}"
    return str(tuple(raw))


def z_signature(v: np.ndarray, decimals: int = 10) -> tuple:
    arr = np.asarray(v, dtype=float).ravel()
    return tuple(float(x) for x in np.round(arr, decimals))


def safe_float(v: Any, default: float = float("nan")) -> float:
    try:
        out = float(v)
    except Exception:
        return float(default)
    return out



def _hash_update_text(h: "hashlib._Hash", value: Any) -> None:
    raw = str(value).encode('utf-8')
    h.update(len(raw).to_bytes(8, byteorder='little', signed=False))
    h.update(raw)


def _hash_update_array(h: "hashlib._Hash", value: Any) -> None:
    arr = np.asarray(value)
    _hash_update_text(h, tuple(int(v) for v in arr.shape))
    if arr.dtype.kind == 'f':
        h.update(b'F8')
        h.update(np.asarray(arr, dtype='<f8').tobytes(order='C'))
    elif arr.dtype.kind in ('i', 'u'):
        h.update(b'I8')
        h.update(np.asarray(arr, dtype='<i8').tobytes(order='C'))
    elif arr.dtype.kind == 'b':
        h.update(b'B1')
        h.update(np.asarray(arr, dtype=np.uint8).tobytes(order='C'))
    else:
        h.update(b'TX')
        for item in arr.ravel().tolist():
            _hash_update_text(h, item)


def instance_block_prefix_hash(inst: "Instance", prefix_blocks: Optional[int] = None) -> str:
    limit = int(inst.S if prefix_blocks is None else prefix_blocks)
    if limit < 0 or limit > int(inst.S):
        raise ValueError(f'prefix_blocks={limit} is outside [0,{int(inst.S)}].')
    h = hashlib.sha256()
    _hash_update_text(h, 'blocks-v1')
    _hash_update_text(h, limit)
    for idx, blk in enumerate(inst.blocks[:limit]):
        _hash_update_text(h, idx)
        for name in ('A', 'B', 'b', 'c', 'lb', 'ub'):
            _hash_update_array(h, getattr(blk, name))
        _hash_update_text(h, ','.join(str(v) for v in blk.vtypes))
    return h.hexdigest()


def instance_first_stage_hash(inst: "Instance") -> str:
    h = hashlib.sha256()
    _hash_update_text(h, 'first-stage-v1')
    for name in ('g', 'z_lb', 'z_ub', 'z_lin_matrix', 'z_lin_rhs'):
        _hash_update_array(h, getattr(inst, name))
    _hash_update_text(h, ','.join(str(v) for v in inst.z_vtypes))
    _hash_update_text(h, ','.join(str(v) for v in inst.z_lin_sense))
    return h.hexdigest()


def instance_tail_domain_hash(inst: "Instance") -> str:
    h = hashlib.sha256()
    _hash_update_text(h, 'domain-v1')
    _hash_update_text(h, instance_first_stage_hash(inst))
    payload = dcap_family_payload(inst)
    for key in ('dcap_tail_cont_enabled', 'dcap_tail_delta', 'dcap_tail_rnc_weight_scale'):
        _hash_update_text(h, key)
        _hash_update_text(h, payload.get(key, None))
    if bool(payload.get('dcap_tail_cont_enabled', False)):
        _hash_update_array(h, dcap_tail_start_vector(inst))
    return h.hexdigest()


def instance_identity_hash(inst: "Instance") -> str:
    h = hashlib.sha256()
    _hash_update_text(h, 'instance-v1')
    _hash_update_text(h, instance_block_prefix_hash(inst))
    _hash_update_text(h, instance_first_stage_hash(inst))
    for name in (
        'item_weights',
        'item_values',
        'initial_capacities',
        'scenario_capacities',
        'scenario_probabilities',
    ):
        _hash_update_array(h, getattr(inst, name))
    _hash_update_text(h, int(inst.S))
    _hash_update_text(h, str(inst.instance_mode))
    return h.hexdigest()


def parse_fixed_int_list(raw: Any, *, field_name: str) -> List[int]:
    text = str(raw or '').replace(';', ',').replace(' ', ',')
    values: List[int] = []
    for token in text.split(','):
        token = token.strip()
        if not token:
            continue
        try:
            value = int(token)
        except Exception as exc:
            raise ValueError(f'{field_name} contains non-integer token {token!r}.') from exc
        if value not in values:
            values.append(value)
    if not values:
        raise ValueError(f'{field_name} must contain at least one integer.')
    return values


def get_four_family_config(family_seed: int) -> Dict[str, Any]:
    seed = int(family_seed)
    if seed not in FOUR_FAMILY_NESTED_CONFIGS:
        raise ValueError(
            f'Unsupported four-family seed {seed}; allowed seeds are '
            f'{sorted(FOUR_FAMILY_NESTED_CONFIGS)}.'
        )
    return dict(FOUR_FAMILY_NESTED_CONFIGS[seed])


def set_gurobi_params(model: "gp.Model", params: Dict[str, Any]) -> None:
    for k, v in params.items():
        try:
            model.setParam(k, v)
        except Exception:
            pass


class TeeRunLogger:
    def __init__(self, path: str, also_stdout: bool = True) -> None:
        ensure_dir(os.path.dirname(path) or ".")
        self._f = open(path, "w", encoding="utf-8")
        self._also_stdout = also_stdout

    def log(self, msg: str = "") -> None:
        if self._also_stdout:
            print(msg, flush=True)
        self._f.write(msg + "\n")
        self._f.flush()

    def close(self) -> None:
        try:
            self._f.close()
        except Exception:
            pass


# ============================================================
# Metrics and logs
# ============================================================

@dataclass
class SolveStats:
    num_lp: int = 0
    num_milp: int = 0
    num_total: int = 0
    solve_time_sec: float = 0.0

    def add(self, runtime: float, is_milp: bool) -> None:
        self.num_total += 1
        if is_milp:
            self.num_milp += 1
        else:
            self.num_lp += 1
        self.solve_time_sec += float(runtime)

    def merge(self, other: "SolveStats") -> None:
        self.num_lp += int(other.num_lp)
        self.num_milp += int(other.num_milp)
        self.num_total += int(other.num_total)
        self.solve_time_sec += float(other.solve_time_sec)


class MetricsLogger:
    def __init__(self, algo_name: str) -> None:
        self.algo = algo_name
        self.rows: List[Dict[str, Any]] = []

    def log(self, **kwargs: Any) -> None:
        self.rows.append(dict(kwargs))

    def to_csv(self, path: str) -> None:
        if not self.rows:
            return
        ensure_dir(os.path.dirname(path) or ".")
        keys = list(self.rows[0].keys())
        with open(path, "w", newline="", encoding="utf-8") as f:
            writer = csv.DictWriter(f, fieldnames=keys)
            writer.writeheader()
            writer.writerows(self.rows)

