@dataclass
class Block:
    A: np.ndarray          # coupling matrix for block variables, size (m_i, n_i)
    B: np.ndarray          # first-stage matrix, size (m_i, d)
    b: np.ndarray          # rhs, size (m_i,)
    c: np.ndarray          # block objective coeffs, size (n_i,)
    vtypes: List[str]      # each in {"B", "I", "C"}
    lb: np.ndarray         # lower bounds, size (n_i,)
    ub: np.ndarray         # upper bounds, size (n_i,)


@dataclass
class Instance:
    blocks: List[Block]
    g: np.ndarray
    z_lb: np.ndarray
    z_ub: np.ndarray
    z_vtypes: List[str]
    z_feas: np.ndarray
    x_feas_blocks: np.ndarray   # shape (P, n_i)
    B_full: np.ndarray
    b_full: np.ndarray
    S: int                      # number of disturbance scenarios / x-blocks
    instance_label: str
    instance_mode: str
    n_items: int
    m_knapsacks: int
    item_weights: np.ndarray
    item_values: np.ndarray
    initial_capacities: np.ndarray
    scenario_capacities: np.ndarray       # shape (P, m)
    scenario_probabilities: np.ndarray    # shape (P,)
    p0: float                             # no-disturbance probability
    no_change_probabilities: np.ndarray   # per-knapsack event probability
    decrease_count_per_knapsack: np.ndarray
    per_knapsack_event_capacities: List[np.ndarray]
    per_knapsack_event_probabilities: List[np.ndarray]
    z_lin_matrix: np.ndarray
