def apply_dcap_tail_continuous_capacity_domain(inst: Instance, args: argparse.Namespace, run_logger: Optional[TeeRunLogger] = None) -> Instance:
    """Capacity-domain adapter: z_i in {0,...,U_i-1} union [U_i,U_i+Delta].

    This function is deliberately an optional post-generator adapter.  When the
    switch is disabled, the input instance is returned unchanged.  When enabled for
    a non-replicated Sun-style integer-capacity DCAP instance, it replaces each
    original capacity variable z_i by (y_i,b_i,u_i), with zcap_i=y_i+u_i entering
    both the coupling/residual matrices and the first-stage purchase cost.
    """
    if not bool(getattr(args, 'dcap_tail_cont_enable', False)):
        return inst
    if not is_dcap_like_instance_mode(inst.instance_mode):
        raise ValueError('--dcap_tail_cont_enable is currently defined only for instance_mode=dcap_like_sun.')
    if str(getattr(args, 'dcap_tail_start_mode', 'ub')).lower().strip() != 'ub':
        raise ValueError('Only --dcap_tail_start_mode ub is supported in 4.7.')
    delta = float(getattr(args, 'dcap_tail_delta', 0.05))
    if delta <= 0.0:
        raise ValueError('--dcap_tail_delta must be > 0.')
    rnc_scale = float(getattr(args, 'dcap_tail_rnc_weight_scale', 0.001))
    if rnc_scale < 0.0:
        raise ValueError('--dcap_tail_rnc_weight_scale must be >= 0.')

    payload0 = dcap_family_payload(inst)
    if str(payload0.get('dcap_z_choice_mode', '')).lower().strip() != 'integer_capacity':
        raise ValueError('tail-continuous capacity domain requires the seed159_sunint integer_capacity DCAP profile.')
    copies = int(payload0.get('dcap_replication_copies', 1) or 1)
    physical_rep = bool(payload0.get('dcap_physical_replication', False))
    d0 = int(payload0.get('dcap_effective_z_dim', int(inst.g.size)) or int(inst.g.size))
    if copies > 1 or physical_rep or int(inst.g.size) != d0:
        raise ValueError(
            '4.7 tail-continuous adapter currently targets the non-replicated seed159_sunint capacity profile. '
            'rep20/rep100 physical profiles remain unchanged when --dcap_tail_cont_enable is not used.'
        )

    old_g = np.asarray(inst.g, dtype=float).ravel().copy()
    old_lb = np.asarray(inst.z_lb, dtype=float).ravel().copy()
    old_ub = np.asarray(inst.z_ub, dtype=float).ravel().copy()
    if old_g.size != d0 or old_lb.size != d0 or old_ub.size != d0:
        raise ValueError('tail-continuous adapter expected the original z vectors to have the effective dimension.')
    tail_start = old_ub.copy()
    y_lb = old_lb.copy()
    y_ub = old_ub.copy()
    b_lb = np.zeros(d0, dtype=float)
    b_ub = np.ones(d0, dtype=float)
    u_lb = np.zeros(d0, dtype=float)
    u_ub = np.full(d0, float(delta), dtype=float)

    # New z layout: y, b, u.  zcap=y+u enters the objective and residual.
    new_g = np.concatenate([old_g, np.zeros(d0, dtype=float), old_g]).astype(float)
    new_z_lb = np.concatenate([y_lb, b_lb, u_lb]).astype(float)
    new_z_ub = np.concatenate([y_ub, b_ub, u_ub]).astype(float)
    new_z_vtypes = ['I'] * d0 + ['B'] * d0 + ['C'] * d0

    new_blocks: List[Block] = []
    for blk in inst.blocks:
        bmat = np.asarray(blk.B, dtype=float)
        if int(bmat.shape[1]) != d0:
            raise ValueError(f'tail-continuous adapter expected each block B to have {d0} columns, got {bmat.shape[1]}.')
        new_B = np.hstack([bmat, np.zeros((int(bmat.shape[0]), d0), dtype=float), bmat]).astype(float)
        new_blocks.append(Block(
            A=np.asarray(blk.A, dtype=float).copy(),
            B=new_B,
            b=np.asarray(blk.b, dtype=float).copy(),
            c=np.asarray(blk.c, dtype=float).copy(),
            vtypes=list(blk.vtypes),
            lb=np.asarray(blk.lb, dtype=float).copy(),
            ub=np.asarray(blk.ub, dtype=float).copy(),
        ))

    # Lift all original z-linear constraints by substituting old z := y + u.
    z_rows: List[np.ndarray] = []
    z_rhs: List[float] = []
    z_sense: List[str] = []
    G0 = np.asarray(inst.z_lin_matrix, dtype=float)
    rhs0 = np.asarray(inst.z_lin_rhs, dtype=float).ravel()
    senses0 = list(inst.z_lin_sense)
    if G0.size:
        for row_idx in range(G0.shape[0]):
            row_old = np.asarray(G0[row_idx, :d0], dtype=float).ravel().copy()
            row_new = np.concatenate([row_old, np.zeros(d0, dtype=float), row_old]).astype(float)
            z_rows.append(row_new)
            z_rhs.append(float(rhs0[row_idx]))
            z_sense.append(str(senses0[row_idx]))

    # Domain logic for each coordinate:
    #   y_i <= U_i - 1 + b_i;  y_i >= U_i b_i;  u_i <= delta b_i.
    for j in range(d0):
        U = float(tail_start[j])
        row = np.zeros(3 * d0, dtype=float)
        row[j] = 1.0
        row[d0 + j] = -1.0
        z_rows.append(row)
        z_rhs.append(float(U - 1.0))
        z_sense.append('<=')

        row = np.zeros(3 * d0, dtype=float)
        row[j] = -1.0
        row[d0 + j] = float(U)
        z_rows.append(row)
        z_rhs.append(0.0)
        z_sense.append('<=')

        row = np.zeros(3 * d0, dtype=float)
        row[2 * d0 + j] = 1.0
        row[d0 + j] = -float(delta)
        z_rows.append(row)
        z_rhs.append(0.0)
        z_sense.append('<=')

    new_payload = copy.deepcopy(payload0)
    new_payload.update({
        'dcap_tail_cont_enabled': True,
        'dcap_tail_delta': float(delta),
        'dcap_tail_start_mode': 'ub',
        'dcap_tail_start': [float(v) for v in tail_start.tolist()],
        'dcap_tail_orig_dim': int(d0),
        'dcap_tail_layout': 'y,b,u',
        'dcap_tail_zcap_definition': 'zcap=y+u',
        'dcap_tail_rnc_weight_scale': float(rnc_scale),
        'dcap_tail_original_z_lb': [float(v) for v in old_lb.tolist()],
        'dcap_tail_original_z_ub': [float(v) for v in old_ub.tolist()],
        'dcap_effective_z_dim': int(d0),
        'dcap_tail_note': '4.7 tail-continuous capacity domain: each original integer capacity coordinate is modeled as y_i,b_i,u_i with zcap_i=y_i+u_i and domain {0,...,U_i-1} U [U_i,U_i+Delta].',
    })

    new_inst = copy.deepcopy(inst)
    new_inst.blocks = new_blocks
    new_inst.g = new_g
    new_inst.z_lb = new_z_lb
    new_inst.z_ub = new_z_ub
    new_inst.z_vtypes = new_z_vtypes
    new_inst.B_full = np.vstack([blk.B for blk in new_blocks]).astype(float)
    new_inst.z_lin_matrix = np.vstack(z_rows).astype(float) if z_rows else np.zeros((0, 3 * d0), dtype=float)
    new_inst.z_lin_rhs = np.asarray(z_rhs, dtype=float)
    new_inst.z_lin_sense = list(z_sense)
    new_inst.family_payload = new_payload
    new_inst.instance_label = str(inst.instance_label) + f'_tailcont_d{str(delta).replace(".", "p")}'
    new_inst.generator_notes = list(inst.generator_notes) + [
        f'4.7 tail-continuous DCAP adapter enabled: original z dimension {d0} is replaced by y/b/u dimension {3*d0}; zcap=y+u enters Bz and the first-stage cost.',
        f'Tail domain per coordinate is {{0,...,U_i-1}} union [U_i,U_i+Delta] with Delta={float(delta):.6g}; tail starts are {tuple(float(v) for v in tail_start.tolist())}.',
        f'RNC tail-u distance scale is {float(rnc_scale):.6g}; use smaller Delta or scale if B40 P1-only shows t=3/t=5 slowdown.',
    ]
    new_inst.benchmark_explanation = list(inst.benchmark_explanation) + [
        'The tail-continuous variant keeps the original integer capacity lattice as the main structure but adds a very small continuous flexibility interval at the highest capacity level.',
        'Because u_i appears in Bz through zcap_i=y_i+u_i, a fixed-z enumerator cannot fully remove the global z coupling when a tail mode is active.',
    ]
    new_inst.z_feas = dcap_tail_project_z(new_inst, np.asarray(inst.z_feas, dtype=float))
    if bool(_FOUR_FAMILY_STRUCTURAL_AUDIT_FAST):
        block_width = int(new_inst.blocks[0].c.size) if new_inst.blocks else 0
        new_inst.x_feas_blocks = np.zeros((int(new_inst.S), block_width), dtype=float)
    else:
        try:
            new_inst.x_feas_blocks = zero_residual_feasible_x_blocks_for_z(new_inst, new_inst.z_feas)
        except Exception:
            new_inst.x_feas_blocks = np.asarray(inst.x_feas_blocks, dtype=float).copy()
    if run_logger is not None:
        run_logger.log('[TailCont] adapter enabled')
        run_logger.log('[TailCont] ' + format_tail_cont_z(new_inst, new_inst.z_feas))
        run_logger.log(f'[TailCont] vars_z old={d0} new={3*d0} delta={float(delta):.6g} rnc_weight_scale={float(rnc_scale):.6g}')
    return new_inst

def dcap_effective_z_vector(inst: Instance, z: np.ndarray) -> np.ndarray:
    """Return the capacity-effective z coordinates.

    Replicated-Z profiles store variables as (r,q).  The displayed physical
    coordinate is z_phys = r + period*q, but the step-1 replicated recourse
    map uses only r = z_phys mod period.  This makes copied physical points
    share the same inner residual/RNC geometry.

    In the optional tail-continuous DCAP adapter, the stored variables are
    z=(y,b,u), while the capacity-effective coordinate is zcap=y+u.
    """
    if dcap_tail_cont_enabled(inst):
        return dcap_tail_decompose_z(inst, z)['zcap'].astype(float).copy()
    payload = dcap_family_payload(inst)
    costs = dcap_tier_costs_from_inst(inst)
    expected = int(costs.size)
    eff_dim = int(payload.get('dcap_effective_z_dim', expected) or expected)
    eff_dim = min(max(1, eff_dim), expected)
    z_arr = np.asarray(z, dtype=float).ravel()
    if z_arr.size < eff_dim:
        raise ValueError(f'dcap effective z reconstruction received size {z_arr.size}, expected at least {eff_dim}.')
    return z_arr[:eff_dim].astype(float).copy()




def dcap_physical_z_vector(inst: Instance, z: np.ndarray) -> np.ndarray:
    """Return the displayed physical replicated-Z coordinates.

    For replicated integer-capacity profiles the actual variable vector is
    z=(r,q).  The physical capacity label is z_phys = r + period*q.  The
    effective inner-recourse coordinate remains r, so copies have identical
    inner residual/RNC geometry in step 1.

    For the tail-continuous adapter, the displayed physical capacity is
    zcap=y+u.
    """
    if dcap_tail_cont_enabled(inst):
        return dcap_tail_decompose_z(inst, z)['zcap'].astype(float).copy()
    payload = dcap_family_payload(inst)
    z_arr = np.asarray(z, dtype=float).ravel()
    eff_dim = int(payload.get('dcap_effective_z_dim', int(z_arr.size)) or int(z_arr.size))
    rep = int(payload.get('dcap_replication_copies', 1) or 1)
    period = int(payload.get('dcap_replication_period', 15) or 15)
    if rep > 1 and 0 < eff_dim and z_arr.size >= 2 * eff_dim:
        r = np.asarray(z_arr[:eff_dim], dtype=float)
        q = np.asarray(z_arr[eff_dim:2 * eff_dim], dtype=float)
        return (r + float(period) * q).astype(float)
    return z_arr.astype(float).copy()


def dcap_replication_decompose_z(inst: Instance, z: np.ndarray) -> Dict[str, Any]:
    payload = dcap_family_payload(inst)
    z_arr = np.asarray(z, dtype=float).ravel()
    eff_dim = int(payload.get('dcap_effective_z_dim', int(z_arr.size)) or int(z_arr.size))
    rep = int(payload.get('dcap_replication_copies', 1) or 1)
    period = int(payload.get('dcap_replication_period', 15) or 15)
    if rep > 1 and 0 < eff_dim and z_arr.size >= 2 * eff_dim:
        r = np.asarray(z_arr[:eff_dim], dtype=float)
        q = np.asarray(z_arr[eff_dim:2 * eff_dim], dtype=float)
        return {
            'is_replicated_z': True,
            'period': int(period),
            'r': r,
            'q': q,
            'physical': r + float(period) * q,
        }
    return {'is_replicated_z': False, 'period': int(period), 'r': z_arr, 'q': np.zeros(0), 'physical': z_arr}


def format_z_for_inst(inst: Instance, z: Optional[np.ndarray]) -> str:
    if z is None:
        return 'NA'
    try:
        if dcap_tail_cont_enabled(inst):
            return format_tail_cont_z(inst, np.asarray(z, dtype=float))
    except Exception:
        pass
    try:
        dec = dcap_replication_decompose_z(inst, np.asarray(z, dtype=float))
        if bool(dec.get('is_replicated_z', False)):
            r = tuple(int(round(float(v))) for v in np.asarray(dec['r'], dtype=float).ravel().tolist())
            q = tuple(int(round(float(v))) for v in np.asarray(dec['q'], dtype=float).ravel().tolist())
            p = tuple(int(round(float(v))) for v in np.asarray(dec['physical'], dtype=float).ravel().tolist())
            return f"phys={p} r={r} q={q}"
    except Exception:
        pass
    return format_int_tuple(np.asarray(z, dtype=float))



@dataclass
class P1EffectiveRepContext:
    """Mapping context for P1's reduced internal r-space on replicated physical profiles."""
    period: int
    copies: int
    eff_dim: int
    physical_dim: int
    q_max: np.ndarray
    copy_reward_per_level: float
    q_const_obj: float
    physical_profile: str

    def internal_r_to_full_z(self, r: np.ndarray) -> np.ndarray:
        r_arr = np.asarray(r, dtype=float).ravel().copy()
        if r_arr.size != int(self.eff_dim):
            raise ValueError(f'internal r has size {r_arr.size}, expected {int(self.eff_dim)}.')
        r_arr = np.round(r_arr).astype(float)
        return np.concatenate([r_arr, np.asarray(self.q_max, dtype=float).ravel().copy()]).astype(float)

    def full_z_to_report_phys(self, z_full: np.ndarray) -> np.ndarray:
        z_arr = np.asarray(z_full, dtype=float).ravel().copy()
        if z_arr.size >= 2 * int(self.eff_dim):
            r = z_arr[: int(self.eff_dim)]
            q = z_arr[int(self.eff_dim): 2 * int(self.eff_dim)]
            return (r + float(self.period) * q).astype(float)
        return z_arr.astype(float)

    def format_internal_and_physical(self, r: Optional[np.ndarray]) -> str:
        if r is None:
            return 'internal_r=NA, fixed_q=NA, z_full=NA, phys=NA'
        z_full = self.internal_r_to_full_z(np.asarray(r, dtype=float))
        phys = self.full_z_to_report_phys(z_full)
        r_tuple = tuple(int(round(float(v))) for v in z_full[: int(self.eff_dim)].tolist())
        q_tuple = tuple(int(round(float(v))) for v in z_full[int(self.eff_dim): 2 * int(self.eff_dim)].tolist())
        z_tuple = tuple(int(round(float(v))) for v in z_full.tolist())
        p_tuple = tuple(int(round(float(v))) for v in phys.tolist())
        return f"internal_r={r_tuple}, fixed_q={q_tuple}, z_full={z_tuple}, phys={p_tuple}"

    def format_full_z(self, z_full: Optional[np.ndarray]) -> str:
        if z_full is None:
            return 'z_full=NA, phys=NA'
        z_arr = np.asarray(z_full, dtype=float).ravel().copy()
        if z_arr.size == int(self.eff_dim):
            return self.format_internal_and_physical(z_arr)
        phys = self.full_z_to_report_phys(z_arr)
        r_tuple = tuple(int(round(float(v))) for v in z_arr[: int(self.eff_dim)].tolist()) if z_arr.size >= int(self.eff_dim) else tuple()
        q_tuple = tuple(int(round(float(v))) for v in z_arr[int(self.eff_dim): 2 * int(self.eff_dim)].tolist()) if z_arr.size >= 2 * int(self.eff_dim) else tuple()
        z_tuple = tuple(int(round(float(v))) for v in z_arr.tolist())
        p_tuple = tuple(int(round(float(v))) for v in phys.tolist())
        return f"internal_r={r_tuple}, fixed_q={q_tuple}, z_full={z_tuple}, phys={p_tuple}"


def is_rep20_physical_profile(args: argparse.Namespace, inst: Instance) -> bool:
    """Return True exactly for the q-active physical replicated-Z profile."""
    try:
        payload = dcap_family_payload(inst)
        profile = str(payload.get('dcap_gurobi_profile', getattr(args, 'dcap_gurobi_profile', '')) or '').lower().strip()
        copies = int(payload.get('dcap_replication_copies', 1) or 1)
        physical_rep = bool(payload.get('dcap_physical_replication', False))
        eff_dim = int(payload.get('dcap_effective_z_dim', 0) or 0)
        return bool(
            is_dcap_like_instance_mode(inst.instance_mode)
            and profile in ('seed159_sunint_rep20_phys', 'seed159_sunint_rep100_phys')
            and physical_rep
            and copies > 1
            and eff_dim > 0
            and int(inst.g.size) >= 2 * int(eff_dim)
        )
    except Exception:
        return False


def get_rep20_q_fixed_constant(inst_or_profile: Any) -> float:
    """Objective constant from analytically fixing q=q_max in the replicated profile."""
    if isinstance(inst_or_profile, Instance):
        inst = inst_or_profile
        payload = dcap_family_payload(inst)
        eff_dim = int(payload.get('dcap_effective_z_dim', max(1, int(inst.g.size) // 2)) or max(1, int(inst.g.size) // 2))
        q_ub = np.asarray(inst.z_ub[eff_dim: 2 * eff_dim], dtype=float).ravel()
        if q_ub.size == 0:
            return 0.0
        q_max = np.round(q_ub).astype(float)
        g_q = np.asarray(inst.g[eff_dim: eff_dim + q_max.size], dtype=float).ravel()
        if g_q.size == q_max.size:
            return float(np.dot(g_q, q_max))
        copy_reward = float(payload.get('dcap_copy_reward_per_level', 0.0) or 0.0)
        return -float(copy_reward) * float(np.sum(q_max))
    # Profile-name fallback for the documented seed159 rep20 setting.
    profile = str(inst_or_profile or '').lower().strip()
    if profile == 'seed159_sunint_rep20_phys':
        return -1.0e-4 * float(19 + 19)
    if profile == 'seed159_sunint_rep100_phys':
        return -1.0e-4 * float(99 + 99)
    return 0.0


def p1_internal_obj_to_physical_obj(obj_internal: float, ctx: Optional[P1EffectiveRepContext]) -> float:
    """Convert an r-only objective without q reward to the physical q-fixed scale."""
    if ctx is None:
        return float(obj_internal)
    return float(obj_internal) + float(ctx.q_const_obj)


def build_p1_effective_internal_instance_from_physical(inst: Instance, args: argparse.Namespace) -> Tuple[Instance, P1EffectiveRepContext]:
    """Build a reduced r-only P1 instance while preserving physical 4D audits.

    The returned instance has z=(r1,r2) only.  The q-copy reward is represented as
    a scalar objective offset, not as a P1 decision variable.  Fixed-z audits must
    map r back to z_full=(r,q_max) and solve the original physical instance.
    """
    payload = dcap_family_payload(inst)
    eff_dim = int(payload.get('dcap_effective_z_dim', 0) or 0)
    if eff_dim <= 0:
        raise ValueError('replicated physical profile is missing dcap_effective_z_dim.')
    physical_dim = int(inst.g.size)
    if physical_dim < 2 * eff_dim:
        raise ValueError(f'physical replicated-Z instance has dim {physical_dim}, expected at least {2 * eff_dim}.')
    period = int(payload.get('dcap_replication_period', 15) or 15)
    copies = int(payload.get('dcap_replication_copies', 20) or 20)
    q_max = np.round(np.asarray(inst.z_ub[eff_dim: 2 * eff_dim], dtype=float).ravel()).astype(float)
    if q_max.size != eff_dim:
        q_max = np.full(eff_dim, float(copies - 1), dtype=float)
    copy_reward = float(payload.get('dcap_copy_reward_per_level', 0.0) or 0.0)
    q_const_obj = float(get_rep20_q_fixed_constant(inst))
    ctx = P1EffectiveRepContext(
        period=int(period),
        copies=int(copies),
        eff_dim=int(eff_dim),
        physical_dim=int(physical_dim),
        q_max=q_max.copy(),
        copy_reward_per_level=float(copy_reward),
        q_const_obj=float(q_const_obj),
        physical_profile=str(payload.get('dcap_gurobi_profile', getattr(args, 'dcap_gurobi_profile', ''))),
    )

    eff_blocks: List[Block] = []
    for blk in inst.blocks:
        B_full = np.asarray(blk.B, dtype=float)
        if B_full.shape[1] < eff_dim:
            raise ValueError('block B has fewer columns than the effective r dimension.')
        eff_blocks.append(Block(
            A=np.asarray(blk.A, dtype=float).copy(),
            B=B_full[:, :eff_dim].copy(),
            b=np.asarray(blk.b, dtype=float).copy(),
            c=np.asarray(blk.c, dtype=float).copy(),
            vtypes=list(blk.vtypes),
            lb=np.asarray(blk.lb, dtype=float).copy(),
            ub=np.asarray(blk.ub, dtype=float).copy(),
        ))

    G_full = np.asarray(inst.z_lin_matrix, dtype=float)
    rhs_full = np.asarray(inst.z_lin_rhs, dtype=float).ravel().copy()
    senses_full = list(inst.z_lin_sense)
    eff_rows: List[np.ndarray] = []
    eff_rhs: List[float] = []
    eff_senses: List[str] = []
    if G_full.size:
        for row_idx in range(G_full.shape[0]):
            row_r = np.asarray(G_full[row_idx, :eff_dim], dtype=float).ravel().copy()
            row_q = np.asarray(G_full[row_idx, eff_dim: 2 * eff_dim], dtype=float).ravel().copy() if G_full.shape[1] >= 2 * eff_dim else np.zeros(eff_dim, dtype=float)
            rhs_adj = float(rhs_full[row_idx]) - float(np.dot(row_q, q_max))
            if np.max(np.abs(row_r)) <= 1e-15:
                # A q-only constraint is either already satisfied by q_max or invalid for this adapter.
                sense = str(senses_full[row_idx]).strip()
                lhs = 0.0
                ok = ((sense in ('<=', 'L') and lhs <= rhs_adj + 1e-8)
                      or (sense in ('>=', 'G') and lhs >= rhs_adj - 1e-8)
                      or (sense in ('=', 'E', '==') and abs(lhs - rhs_adj) <= 1e-8))
                if not ok:
                    raise ValueError('fixed q_max violates a q-only z linear constraint in the physical instance.')
                continue
            eff_rows.append(row_r)
            eff_rhs.append(float(rhs_adj))
            eff_senses.append(str(senses_full[row_idx]))
    z_lin_matrix_eff = np.vstack(eff_rows).astype(float) if eff_rows else np.zeros((0, eff_dim), dtype=float)
    z_lin_rhs_eff = np.asarray(eff_rhs, dtype=float) if eff_rhs else np.zeros(0, dtype=float)

    payload_eff = copy.deepcopy(payload)
    payload_eff.update({
        'p1_effective_internal_enabled': True,
        'p1_effective_internal_note': 'P1 uses reduced r-space; q is analytically fixed to q_max and appears only as an objective constant plus physical fixed-z audit mapping.',
        'p1_objective_constant_offset': float(q_const_obj),
        'p1_effective_internal_dim': int(eff_dim),
        'p1_effective_physical_dim': int(physical_dim),
        'p1_effective_fixed_q': [float(v) for v in q_max.tolist()],
        'p1_effective_q_const_obj': float(q_const_obj),
    })

    z_feas_eff = np.asarray(inst.z_feas[:eff_dim], dtype=float).copy()
    effective_inst = Instance(
        blocks=eff_blocks,
        g=np.asarray(inst.g[:eff_dim], dtype=float).copy(),
        z_lb=np.asarray(inst.z_lb[:eff_dim], dtype=float).copy(),
        z_ub=np.asarray(inst.z_ub[:eff_dim], dtype=float).copy(),
        z_vtypes=list(inst.z_vtypes[:eff_dim]),
        z_feas=z_feas_eff,
        x_feas_blocks=np.asarray(inst.x_feas_blocks, dtype=float).copy(),
        B_full=np.vstack([blk.B for blk in eff_blocks]).astype(float),
        b_full=np.asarray(inst.b_full, dtype=float).copy(),
        S=int(inst.S),
        instance_label=str(inst.instance_label) + '_P1EffectiveR',
        instance_mode=str(inst.instance_mode),
        n_items=int(inst.n_items),
        m_knapsacks=int(inst.m_knapsacks),
        item_weights=np.asarray(inst.item_weights, dtype=float).copy(),
        item_values=np.asarray(inst.item_values, dtype=float).copy(),
        initial_capacities=np.asarray(inst.initial_capacities, dtype=float).copy(),
        scenario_capacities=np.asarray(inst.scenario_capacities, dtype=float).copy(),
        scenario_probabilities=np.asarray(inst.scenario_probabilities, dtype=float).copy(),
        p0=float(inst.p0),
        no_change_probabilities=np.asarray(inst.no_change_probabilities, dtype=float).copy(),
        decrease_count_per_knapsack=np.asarray(inst.decrease_count_per_knapsack, dtype=int).copy(),
        per_knapsack_event_capacities=[np.asarray(v, dtype=float).copy() for v in inst.per_knapsack_event_capacities],
        per_knapsack_event_probabilities=[np.asarray(v, dtype=float).copy() for v in inst.per_knapsack_event_probabilities],
        z_lin_matrix=z_lin_matrix_eff,
        z_lin_rhs=z_lin_rhs_eff,
        z_lin_sense=list(eff_senses),
        generator_notes=list(inst.generator_notes),
        generator_metrics=dict(inst.generator_metrics),
        generator_score=float(inst.generator_score),
        benchmark_explanation=list(inst.benchmark_explanation),
        family_payload=payload_eff,
    )
    effective_inst.z_feas = project_z_to_nominal_feasible(effective_inst, effective_inst.z_feas)
    try:
        effective_inst.x_feas_blocks = zero_residual_feasible_x_blocks_for_z(effective_inst, effective_inst.z_feas)
    except Exception:
        effective_inst.x_feas_blocks = np.asarray(inst.x_feas_blocks, dtype=float).copy()
    return effective_inst, ctx

def dcap_capacity_from_z(inst: Instance, z: np.ndarray) -> np.ndarray:
    tier_caps = dcap_tier_capacities_from_inst(inst)
    n_resources, n_periods, n_tiers = tier_caps.shape
    z_eff = dcap_effective_z_vector(inst, z)
    if z_eff.size != n_resources * n_periods * n_tiers:
        raise ValueError('dcap capacity reconstruction received an effective z vector with incompatible dimension.')
    z_mat = z_eff.reshape(n_resources, n_periods, n_tiers)
    return np.sum(tier_caps * z_mat, axis=2).astype(float)



def dcap_purchase_cost_from_z(inst: Instance, z: np.ndarray) -> float:
    costs = dcap_tier_costs_from_inst(inst)
    z_eff = dcap_effective_z_vector(inst, z).reshape(costs.shape)
    return float(np.sum(costs * z_eff))


def normalize_dcap_gurobi_profile(profile_name: str) -> str:
    raw = str(profile_name or 'balanced').lower().strip()
    aliases = {
        'default': 'balanced',
        'auto': 'seed159',
        'seed_159': 'seed159',
        'seed-159': 'seed159',
        'seed159_balanced': 'seed159',
        'soft': 'seed159_soft',
        'harder': 'seed159_harder',
        'efhard': 'seed159_efhard',
        'ef_hard': 'seed159_efhard',
        'gurobi_hard': 'seed159_efhard',
        'seed159_hard': 'seed159_efhard',
        'efhard_soft': 'seed159_efhard_soft',
        'gurobi_hard_soft': 'seed159_efhard_soft',
        'facility': 'seed159_facility',
        'facility_open': 'seed159_facility',
        'fixed_charge': 'seed159_facility',
        'ef_facility': 'seed159_facility',
        'sunint': 'seed159_sunint',
        'sun_integer': 'seed159_sunint',
        'integer_z': 'seed159_sunint',
        'sunstyle': 'seed159_sunint',
        'rep20': 'seed159_sunint_rep20_phys',
        'replicated20': 'seed159_sunint_rep20_phys',
        'sunint_rep20': 'seed159_sunint_rep20_phys',
        'modular20': 'seed159_sunint_rep20_phys',
        'rep20_phys': 'seed159_sunint_rep20_phys',
        'physical_rep20': 'seed159_sunint_rep20_phys',
        'rep100': 'seed159_sunint_rep100_phys',
        'replicated100': 'seed159_sunint_rep100_phys',
        'sunint_rep100': 'seed159_sunint_rep100_phys',
        'modular100': 'seed159_sunint_rep100_phys',
        'rep100_phys': 'seed159_sunint_rep100_phys',
        'physical_rep100': 'seed159_sunint_rep100_phys',
    }
    raw = aliases.get(raw, raw)
    allowed = {'balanced', 'seed159', 'seed159_soft', 'seed159_harder', 'seed159_efhard', 'seed159_efhard_soft', 'seed159_facility', 'seed159_sunint', 'seed159_sunint_rep20', 'seed159_sunint_rep20_phys', 'seed159_sunint_rep100_phys'}
    if raw not in allowed:
        raise ValueError(f'Unsupported dcap_gurobi_profile {profile_name!r}; expected one of {sorted(allowed)}.')
    return raw


