def build_argparser() -> argparse.ArgumentParser:
    p = argparse.ArgumentParser(
        description=(
            "P1' driver on structured two-block benchmark instances with an explicit Pessoa-style out/in/sep "
            'outer state machine over the current sharp-AL master/oracle framework.'
        )
    )
    p.add_argument('--n_items', type=int, default=6, help='number of items in SMKP modes, or local tasks per x-block in dcap_like_sun; the small benchmark scale uses 6')
    p.add_argument('--n_knapsacks', type=int, default=3, help='number of knapsacks in SMKP/GA-like modes, or resource families in dcap_like_sun; the small benchmark scale uses 3')
    p.add_argument('--instance_seed', type=int, default=1, help='seed for random SMKP instance generation')
    p.add_argument('--solver_seed', type=int, default=None, help='optional distinct Gurobi seed; defaults to instance_seed')

    p.add_argument('--item_R', type=int, default=30, help='strongly correlated item parameter R from Section 4')
    p.add_argument('--scenario_u', type=float, default=0.5, help='lower fraction u for reduced capacities in Section 4.3')
    p.add_argument('--scenario_relprob_r', type=float, default=3.0, help='relative-probability parameter r from Section 4')
    p.add_argument('--uncertain_prob_D', type=float, default=1.0, help='probability D that a knapsack is uncertain; default 1.0 for the many-scenarios direction')
    p.add_argument('--no_change_prob_low', type=float, default=0.1)
    p.add_argument('--no_change_prob_high', type=float, default=0.9)
    p.add_argument('--decrease_count_low', type=int, default=5, help='transparent completion: lower bound on per-knapsack number of possible decreases')
    p.add_argument('--decrease_count_high', type=int, default=7, help='transparent completion: upper bound on per-knapsack number of possible decreases')
    p.add_argument('--target_scenarios_min', type=int, default=202, help='Table 8 lower end of the many-scenarios range')
    p.add_argument('--target_scenarios_max', type=int, default=467, help='Table 8 upper end of the many-scenarios range')
    p.add_argument('--scenario_retry_limit', type=int, default=2000, help='instance-generator retry limit for hitting the target scenario window')
    p.add_argument('--instance_mode', choices=['table8_default', 'stabilization_stress', 'pessoa_favorable', 'ga_like_sun', 'dcap_like_sun'], default='table8_default', help='default Table-8-like family, fair stabilization_stress family, the GA-like Sun benchmark family, or the new DCAP-like Sun benchmark family')
    p.add_argument('--stress_search_attempts', type=int, default=8, help='number of deterministic candidate attempts searched by the structural benchmark selector')
    p.add_argument('--stress_near_tie_abs_gap', type=float, default=1.5, help='absolute near-tie threshold used by the static benchmark scorer')
    p.add_argument('--ga_num_blocks', type=int, default=18, help='number of heterogeneous x-blocks when instance_mode=ga_like_sun')
    p.add_argument('--ga_nominal_mass', type=float, default=0.12, help='nominal first-stage reward mass p0 when instance_mode=ga_like_sun')
    p.add_argument('--dcap_num_blocks', type=int, default=18, help='number of local scenario x-blocks when instance_mode=dcap_like_sun')
    p.add_argument('--dcap_periods', type=int, default=2, help='number of coarse capacity-purchase periods when instance_mode=dcap_like_sun')
    p.add_argument('--dcap_tiers', type=int, default=2, help='number of purchasable capacity tiers per resource-period when instance_mode=dcap_like_sun')
    p.add_argument('--dcap_budget_tightness', type=float, default=0.67, help='fraction of full first-stage purchase cost available as the shared budget when instance_mode=dcap_like_sun')
