            compare_row = build_compare_summary_row(p1_row, p2_row)
            write_csv([p1_row, p2_row], os.path.join(out_dir, 'compare_results.csv'))
            write_csv([compare_row], os.path.join(out_dir, 'compare_group_summary.csv'))
            write_compare_report(os.path.join(out_dir, 'compare_report.md'), args=args, inst=inst, p1_row=p1_row, p2_row=p2_row, compare_row=compare_row)
            run_logger.log('')
            run_logger.log('[summary]')
            run_logger.log(json.dumps(p1_row, ensure_ascii=False))
            run_logger.log(json.dumps(p2_row, ensure_ascii=False))
            run_logger.log(json.dumps(compare_row, ensure_ascii=False))
            run_logger.log(f"p1prime_log.csv         -> {os.path.join(out_dir, 'p1prime_log.csv')}")
            run_logger.log(f"p2_theory_log.csv       -> {os.path.join(out_dir, 'p2_theory_log.csv')}")
